def _ensure_manifest_extends(previous: list[list[Any]],
                             current: list[list[Any]]) -> None:
    # Within one generation the old manifest must survive item for item;
    # the new page may only interleave or append new audit keys. A
    # dropped key, a rewritten event or a reordered page is a regression.
    current_map = {event_key: event for event_key, event in current}
    for event_key, event in previous:
        current_event = current_map.get(event_key)
        if current_event is None or current_event != event:
            raise ValueError("a generation only accepts its existing "
                             "events unchanged and new audit keys")
    cursor = iter(previous)
    expected = next(cursor, None)
    for event_key, event in current:
        if expected is not None and event_key == expected[0]:
            if event != expected[1]:
                raise ValueError("a generation only accepts its existing "
                                 "events unchanged and new audit keys")
            expected = next(cursor, None)
    if expected is not None:
        raise ValueError("a generation only accepts its existing events "
                         "unchanged and new audit keys")

